head.b:skin:
  :root{
    --ink:#1b1b2f;
    --bg-main:#d9d4bd;
    --bg-panel:#f3efe1;
    --red:#ff4d5e;
    --mint:#2fbd8e;
    --yellow:#ffce3d;
    --shadow: 6px 6px 0 var(--ink);
  }
  *{box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    margin:0;
    background:var(--bg-main);
    color:var(--ink);
    font-family:'Space Mono', monospace;
    line-height:1.6;
    background-image: radial-gradient(var(--ink) 1px, transparent 1px);
    background-size: 24px 24px;
    background-position: -12px -12px;
  }
  ::selection{ background:var(--red); color:var(--bg-panel); }
  h1,h2,h3,.pixel-font{
    font-family:'Press Start 2P', monospace;
    line-height:1.5;
    letter-spacing:0.5px;
  }
  a{ color:inherit; }
  .wrap{ max-width:1080px; margin:0 auto; padding:0 24px; }

  .pixel-frame{
    background:var(--bg-panel);
    border:3px solid var(--ink);
    box-shadow: var(--shadow);
    clip-path: polygon(0 12px,12px 12px,12px 0,calc(100% - 12px) 0,calc(100% - 12px) 12px,100% 12px,100% calc(100% - 12px),calc(100% - 12px) calc(100% - 12px),calc(100% - 12px) 100%,12px 100%,12px calc(100% - 12px),0 calc(100% - 12px));
  }
  .pixel-btn{
    display:inline-block;
    font-family:'Press Start 2P', monospace;
    font-size:11px;
    padding:14px 20px;
    background:var(--yellow);
    color:var(--ink);
    border:3px solid var(--ink);
    text-decoration:none;
    box-shadow: 5px 5px 0 var(--ink);
    clip-path: polygon(0 8px,8px 8px,8px 0,calc(100% - 8px) 0,calc(100% - 8px) 8px,100% 8px,100% calc(100% - 8px),calc(100% - 8px) calc(100% - 8px),calc(100% - 8px) 100%,8px 100%,8px calc(100% - 8px),0 calc(100% - 8px));
    transition: transform .08s steps(2), box-shadow .08s steps(2);
    cursor:pointer;
  }
  .pixel-btn:hover{ transform: translate(3px,3px); box-shadow: 2px 2px 0 var(--ink); }
  .pixel-btn.alt{ background:var(--mint); }
  .pixel-btn.red{ background:var(--red); color:var(--bg-panel); }

  header.site-header{ position:sticky; top:0; z-index:50; background:var(--bg-panel); border-bottom:3px solid var(--ink); }
  nav.wrap{ display:flex; align-items:center; justify-content:space-between; padding:14px 24px; }
  .logo{ display:flex; align-items:center; gap:10px; font-family:'Press Start 2P', monospace; font-size:14px; text-decoration:none; color:var(--ink); }
  .logo img{ image-rendering:pixelated; display:block; }
  nav ul{ list-style:none; display:flex; gap:22px; margin:0; padding:0; font-size:13px; }
  nav ul a{ text-decoration:none; border-bottom:2px solid transparent; }
  nav ul a:hover{ border-bottom:2px solid var(--red); }

  .hero{ position:relative; overflow:hidden; border-bottom:3px solid var(--ink);
    background: linear-gradient(rgba(27,27,47,0.06) 50%, transparent 50%), var(--bg-main);
    background-size: 100% 4px, 100% 100%; }
  .hero-inner{ padding:96px 24px 84px; text-align:center; position:relative; }
  .boot-line{ font-size:12px; color:var(--mint); background:var(--ink); display:inline-block; padding:6px 12px; margin-bottom:28px; }
  .boot-line::after{ content:"█"; animation: blink 1s steps(1) infinite; margin-left:4px; }
  @keyframes blink{ 50%{ opacity:0; } }
  .hero-banner{ image-rendering:pixelated; display:block; margin:0 auto 28px; max-width:90%; height:auto; width:520px; }
  .hero .tagline{ font-family:'Press Start 2P', monospace; font-size:clamp(14px,2.6vw,20px); line-height:1.6; margin:0 0 20px; }
  .hero .tagline .hl{ color:var(--red); }
  .hero p.sub{ max-width:560px; margin:0 auto 36px; font-size:17px; font-family:'Space Mono', monospace; }
  .hero-ctas{ display:flex; gap:16px; justify-content:center; flex-wrap:wrap; }
  .sprite-row{ display:flex; justify-content:center; gap:18px; margin-top:64px; flex-wrap:wrap; }
  .sprite-row svg{ image-rendering:pixelated; }
  .sprite{ animation: floaty 2.4s ease-in-out infinite; }
  .sprite:nth-child(2){ animation-delay:.3s; }
  .sprite:nth-child(3){ animation-delay:.6s; }
  .sprite:nth-child(4){ animation-delay:.9s; }
  @keyframes floaty{ 0%,100%{ transform:translateY(0); } 50%{ transform:translateY(-8px); } }

  section{ padding:88px 0; }
  .eyebrow{ font-family:'Press Start 2P', monospace; font-size:11px; color:var(--red); margin-bottom:14px; }
  .section-head{ max-width:620px; margin-bottom:48px; }
  .section-head h2{ font-size:clamp(20px,3vw,28px); margin:0 0 14px; }
  .section-head p{ margin:0; font-size:15.5px; }

  .about-grid{ display:grid; grid-template-columns: 1.1fr 0.9fr; gap:48px; align-items:center; }
  .palette{ display:flex; gap:0; border:3px solid var(--ink); box-shadow:var(--shadow); }
  .palette div{ height:120px; flex:1; }
  .about-copy p{ font-size:15.5px; }
  .about-copy .stat-row{ display:flex; gap:32px; margin-top:28px; }
  .stat b{ font-family:'Press Start 2P'; font-size:20px; display:block; margin-bottom:6px; color:var(--red); }
  .stat span{ font-size:12.5px; }

  .cart-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:28px; }
  .cart{ padding:26px; }
  .cart .num{ font-family:'Press Start 2P'; font-size:11px; color:var(--mint); margin-bottom:16px; display:block; }
  .cart h3{ font-size:15px; margin:0 0 12px; }
  .cart p{ font-size:14.5px; margin:0; }

  .gallery{ display:grid; grid-template-columns:repeat(4,1fr); gap:16px; }
  .tile{ aspect-ratio:1; border:3px solid var(--ink); overflow:hidden; display:flex; align-items:center; justify-content:center; box-shadow: 4px 4px 0 var(--ink); }
  .tile svg{ width:70%; height:70%; image-rendering:pixelated; }
  .tile:nth-child(1){ background:#ffd9dd; }
  .tile:nth-child(2){ background:#d7f5e9; }
  .tile:nth-child(3){ background:#fff2c9; }
  .tile:nth-child(4){ background:#dcd9f7; }
  .tile:nth-child(5){ background:#cfeeff; }
  .tile:nth-child(6){ background:#ffe0c2; }
  .tile:nth-child(7){ background:#e4f4c9; }
  .tile:nth-child(8){ background:#f6d6f0; }

  /* live Blogger post list, styled as cartridge cards */
  .post-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:28px; }
  .post-grid .date-outer, .post-grid .blog-posts, .post-grid .post-outer-container{ display:contents; }
  .post-card{ padding:0; overflow:hidden; }
  .post-thumb{ height:150px; background: repeating-linear-gradient(45deg, var(--ink) 0 4px, transparent 4px 8px); background-color: var(--yellow); border-bottom:3px solid var(--ink); }
  .post-thumb img{ width:100%; height:100%; object-fit:cover; display:block; }
  .post-body{ padding:20px; }
  .post-body .tag{ font-size:11px; color:var(--mint); margin-bottom:10px; display:block; }
  .post-body h3{ font-size:14.5px; margin:0 0 10px; }
  .post-body h3 a{ text-decoration:none; }
  .post-body p{ font-size:13.5px; margin:0 0 14px; }
  .post-body a.readmore{ font-size:12px; text-decoration:none; border-bottom:2px solid var(--red); }
  .blog-pager{ text-align:center; margin-top:48px; font-family:'Press Start 2P'; font-size:11px; }
  .blog-pager a{ text-decoration:none; border-bottom:2px solid var(--red); }
  .status-msg-body{ text-align:center; font-size:14px; }

  .newsletter{ background:var(--ink); color:var(--bg-panel); border-top:3px solid var(--ink); border-bottom:3px solid var(--ink); }
  .newsletter .wrap{ text-align:center; }
  .newsletter h2{ color:var(--yellow); font-size:clamp(18px,3vw,24px); margin:0 0 14px; }
  .newsletter p{ margin:0 0 30px; opacity:.85; }
  .n-form{ display:flex; gap:12px; justify-content:center; max-width:420px; margin:0 auto; flex-wrap:wrap; }
  .n-form input{ flex:1; min-width:200px; padding:14px; border:3px solid var(--bg-panel); background:transparent; color:var(--bg-panel); font-family:'Space Mono'; font-size:14px; }
  .n-form input::placeholder{ color:#a9a6c4; }

  footer.site-footer{ padding:48px 0 36px; }
  .foot-grid{ display:flex; justify-content:space-between; flex-wrap:wrap; gap:24px; align-items:flex-end; }
  .foot-links{ display:flex; gap:20px; list-style:none; padding:0; margin:0; font-size:13px; }
  .foot-links a{ text-decoration:none; }
  .foot-links a:hover{ color:var(--red); }
  .copyright{ font-size:12px; opacity:.7; margin-top:24px; }

  /* single post page */
  .single-post{ max-width:720px; margin:0 auto; padding:64px 24px; }
  .single-post h1{ font-size:22px; margin-bottom:20px; }
  .single-post .post-content{ font-family:'Space Mono'; font-size:15.5px; }
  .single-post .post-content img{ max-width:100%; border:3px solid var(--ink); }
  .comments{ margin-top:48px; }

  @media (max-width: 860px){
    .about-grid, .cart-grid, .post-grid{ grid-template-columns:1fr; }
    .gallery{ grid-template-columns:repeat(2,1fr); }
    nav ul{ display:none; }
  }
  @media (prefers-reduced-motion: reduce){ *{ animation:none !important; transition:none !important; } }

  /* Interactive Bronco gallery */
  .garage{ margin-top:56px; scroll-margin-top:90px; }
  .foot-links{flex-wrap:wrap;}
  .garage .section-head{ margin-bottom:24px; }
  .garage-frame{ display:block; width:100%; height:640px; border:3px solid var(--ink); background:var(--bg-panel); box-shadow:var(--shadow); }
  .garage-link{ display:inline-block; margin-top:20px; font-size:13px; text-underline-offset:4px; }
  @media(max-width:600px){ .garage-frame{height:680px;} .wrap{padding-left:18px;padding-right:18px;} .hero-inner{padding-top:64px;} }

  /* Whole-page CRT glass: the embedded viewer has its own stronger treatment. */
  body::before, body::after{content:"";position:fixed;inset:0;pointer-events:none;z-index:1000}
  body::before{background:repeating-linear-gradient(to bottom,rgba(27,27,47,.12) 0,rgba(27,27,47,.12) 1px,transparent 1px,transparent 4px),linear-gradient(90deg,rgba(255,50,70,.035),transparent 22%,transparent 78%,rgba(47,189,142,.035));mix-blend-mode:multiply;opacity:.95}
  body::after{background:radial-gradient(ellipse at center,transparent 48%,rgba(27,27,47,.2) 100%);box-shadow:inset 0 0 70px rgba(27,27,47,.17)}
  .crt-text, .crt-text h1, .crt-text h2, .crt-text h3, .crt-text p, .crt-text a, .crt-text button, .crt-text label, .crt-text span, .crt-text li, .crt-text select{ text-shadow:.06rem 0 .06rem rgba(234,54,175,.58),-.125rem 0 .06rem rgba(117,250,105,.46); }
  .crt-text{filter:url(#crt-curve);}
  @media (prefers-reduced-motion:no-preference){body::before{animation:crt-breathe 8s steps(2,end) infinite}.crt-text{animation:textflicker .08s infinite alternate}@keyframes crt-breathe{0%,100%{opacity:.88}50%{opacity:1}}@keyframes textflicker{from{text-shadow:1px 0 0 rgba(234,54,175,.5),-2px 0 0 rgba(117,250,105,.4)}to{text-shadow:2px .5px 2px rgba(234,54,175,.68),-1px -.5px 2px rgba(117,250,105,.54)}}}












/* pix-motion:start */
/* Progressive enhancement: the document remains readable without JavaScript. */
html { scroll-padding-top: 100px; }
body { overflow-x: clip; }
html.booting, .garage-frame { overflow-anchor: none; }
/* A filter on body would turn fixed loaders and sticky navigation into scrolling layers. */
body.crt-text { filter: none; }
.hero-banner, .sprite-row, .tile svg { filter: url(#crt-curve); }
.site-header { isolation: isolate; }
.scroll-meter { position: absolute; bottom: -3px; left: 0; width: 100%; height: 3px; background: var(--red); transform: scaleX(var(--page-progress,0)); transform-origin: left; }
.motion-toggle { border: 1px solid currentColor; background: transparent; color: inherit; font: 10px 'Space Mono', monospace; cursor: pointer; padding: 6px 8px; white-space: nowrap; }
.motion-toggle:hover, .motion-toggle:focus-visible { background: var(--ink); color: var(--bg-panel); }
.motion-ready section, .motion-ready footer { position: relative; overflow-x: clip; }
.hero { min-height: min(960px, 100svh); display: grid; align-items: center; }
.hero-inner { width: 100%; }
.hero-orbit { position: absolute; inset: 10% 8%; border: 1px solid rgba(27,27,47,.16); border-radius: 50%; pointer-events: none; transform: rotate(-22deg); }
.hero-orbit::before, .hero-orbit::after { content: ''; position: absolute; width: 22px; height: 22px; border: 3px solid var(--ink); background: var(--mint); top: 12%; left: 14%; box-shadow: 4px 4px 0 var(--ink); }
.hero-orbit::after { background: var(--red); top: auto; left: auto; right: 10%; bottom: 15%; width: 34px; height: 34px; }
.scroll-cue { display: block; width: max-content; margin: 34px auto 0; text-transform: uppercase; font-size: 10px; letter-spacing: 3px; text-decoration: none; }
.scroll-cue span { display: inline-block; margin-left: 10px; animation: cue-drop 1.4s ease-in-out infinite; }
@keyframes cue-drop { 50% { transform: translateY(7px); } }
.motion-word { display: inline-block; }
.scroll-story { padding: 0; background: var(--ink); color: var(--bg-panel); overflow: clip; }
.story-pin { min-height: 85svh; display: flex; flex-direction: column; justify-content: space-between; padding: 40px 5vw; }
.story-label, .story-bottom { font-size: 10px; letter-spacing: 2px; }
.story-label { color: var(--mint); }
.story-bottom { display: flex; justify-content: space-between; gap: 20px; }
.story-lines { padding-block: 60px; }
.story-line { font-family: 'Press Start 2P', monospace; font-size: clamp(20px, 4.6vw, 76px); line-height: 1.8; letter-spacing: -.05em; white-space: nowrap; }
.story-line:nth-child(2) { text-align: right; color: var(--yellow); }
.story-line em { font-style: normal; color: var(--mint); }
.story-line:nth-child(2) em { color: var(--red); }
.motion-ready .scroll-story { height: 220svh; }
.motion-ready .story-pin { position: sticky; top: 72px; height: calc(100svh - 72px); min-height: 0; }
.motion-ready .about-copy h2 { font-size: clamp(23px, 3.7vw, 42px); line-height: 1.65; }
.motion-ready .section-head h2 { font-size: clamp(25px, 4.2vw, 48px); line-height: 1.5; }
.motion-ready .section-head { max-width: 840px; }
.motion-ready #about { padding-top: 130px; padding-bottom: 130px; }
.motion-ready .palette { height: 250px; align-items: stretch; transform-origin: center; }
.motion-ready .palette div { height: auto; }
.motion-ready .cart-grid { perspective: 1000px; gap: 32px; }
.motion-ready .cart { min-height: 310px; display: flex; flex-direction: column; justify-content: center; }
.motion-ready .cart .num { font-size: 32px; margin-bottom: 28px; }
.motion-ready .cart:nth-child(2) { background: var(--yellow); }
.motion-ready .cart:nth-child(3) { background: var(--mint); }
.motion-ready .cart:nth-child(3) .num { color: var(--ink); }
.motion-band { overflow: hidden; padding: 25px 0; border-block: 3px solid var(--ink); background: var(--yellow); }
.motion-band:nth-of-type(even) { background: var(--mint); }
.motion-band-track { display: flex; width: max-content; gap: 40px; align-items: center; font-family: 'Press Start 2P', monospace; font-size: clamp(23px, 5vw, 70px); line-height: 1.3; white-space: nowrap; }
.motion-band-track span:nth-child(even) { color: transparent; -webkit-text-stroke: 1.5px var(--ink); }
.motion-band-track i { font-style: normal; color: var(--red); }
.motion-ready .gallery-stage { height: 260svh; position: relative; margin-inline: calc(50% - 50vw); }
.motion-ready .gallery-pin { position: sticky; top: 80px; height: calc(100svh - 80px); overflow: hidden; display: flex; flex-direction: column; justify-content: center; gap: 30px; padding: 28px max(24px, calc((100vw - 1032px)/2)); }
.gallery-caption { display: flex; justify-content: space-between; gap: 16px; text-transform: uppercase; font-size: 11px; letter-spacing: 2px; }
.motion-ready .gallery-stage .gallery { display: flex; width: max-content; gap: 30px; }
.motion-ready .gallery-stage .tile { flex: 0 0 min(42vw, 430px, 52svh); width: min(42vw, 430px, 52svh); position: relative; }
.motion-ready .gallery-stage .tile::after { content: attr(data-index); position: absolute; bottom: 10px; left: 16px; font-size: 11px; }
.motion-ready .gallery-stage .tile svg { transition: transform .45s ease; }
.motion-ready .gallery-stage .tile:hover svg { transform: rotate(-8deg) scale(1.12); }
.gallery-progress { height: 3px; background: rgba(27,27,47,.18); }
.gallery-progress span { height: 100%; display: block; background: var(--red); transform-origin: left; transform: scaleX(var(--gallery-progress,0)); }
.motion-ready .garage { margin-top: 110px; }
.motion-ready .garage-frame { transform-origin: center; }
.garage .garage-frame { width: var(--viewport-width, 100vw); margin-inline: calc((100% - var(--viewport-width, 100vw)) / 2); height: calc(100svh - var(--header-height, 70px)); min-height: 600px; border: 0; box-shadow: none; }
.motion-ready .newsletter { padding-block: 120px; overflow: hidden; }
.motion-ready .newsletter h2 { font-size: clamp(26px, 5vw, 58px); }
.contact-title { font-family: 'Press Start 2P', monospace; font-size: clamp(30px, 7vw, 82px); line-height: 1.5; margin: 0 0 45px; }
.contact-title .contact-arrow { color: var(--red); display: inline-block; }
.motion-ready .site-footer { padding-block: 100px 38px; }
.foot-links a { display: inline-block; transition: transform .2s, color .2s; }
.foot-links a:hover { transform: translateY(-4px); }
.asset-notice { background: var(--yellow); color: var(--ink); padding: 12px 24px; font-size: 12px; border-bottom: 2px solid var(--ink); }
.asset-notice a { margin-left: 12px; }

/* The movie occupies the entire viewport, with only a small loading HUD. */
.site-loader { position: fixed; inset: 0; z-index: 10000; background: #000; color: #fff; display: none; overflow: hidden; font-family: 'Space Mono', monospace; }
html.booting { overflow: hidden; }
.booting .site-loader { display: block; }
.site-loader .loader-film { position: absolute; inset: 0; width: 100%; height: 100%; max-height: none; aspect-ratio: auto; object-fit: cover; display: block; }
.loader-hud { position: absolute; bottom: max(34px, env(safe-area-inset-bottom)); left: 4vw; width: min(420px, 66vw); z-index: 1; text-shadow: none; }
.loader-bottom { display: flex; justify-content: space-between; gap: 16px; align-items: center; text-transform: uppercase; font-size: 10px; letter-spacing: 2px; }
.loader-status, .loader-percent { text-shadow: none !important; }
.loader-percent { font-size: 14px; color: #ffce3d; }
.loader-bar { height: 2px; margin-top: 12px; background: #333; }
.loader-bar span { display: block; height: 100%; background: #ffce3d; transform: scaleX(var(--load-progress,0)); transform-origin: left; transition: transform .3s; }
.loader-play, .loader-retry { background: #000b; color: #fff; border: 1px solid #999; padding: 12px 16px; margin-top: 16px; font: 11px 'Space Mono', monospace; cursor: pointer; }
.loader-leaving { pointer-events: none; animation: loader-out .9s cubic-bezier(.76,0,.24,1) forwards; }
@keyframes loader-out { to { clip-path: inset(0 0 100% 0); } }

/* A full-height opening scene replaces the short, static paper-like hero. */
.logo { gap: 0; }
.logo img { margin-right: 0; width: 19px; height: 28px; object-fit: contain; }
.motion-ready .hero-stage { height: 210svh; }
.motion-ready .hero { position: sticky; top: var(--header-height, 70px); height: calc(100svh - var(--header-height, 70px)); min-height: 0; }
.hero { background: #10101d; color: var(--bg-panel); }
.hero-inner { padding-block: 48px; }
.hero-banner { width: min(720px, 80vw); filter: brightness(0) invert(1); }
.hero-orbit { border-color: #ffffff24; }
.hero-orbit::before, .hero-orbit::after { box-shadow: 0 0 35px #2fbd8e66; border-color: var(--mint); }
.motion-ready .scroll-story { height: 320svh; }
.motion-ready .story-pin, .motion-ready .gallery-pin { top: var(--header-height, 70px); height: calc(100svh - var(--header-height, 70px)); }
#about { background: #cee9c9; }
#offerings { background: #11111e; color: var(--bg-panel); }
#offerings .cart { color: var(--ink); }
#gallery { background: #e9dfc3; }
.motion-ready .motion-word { will-change: transform, opacity; }
.motion-ready .palette { box-shadow: 18px 18px 0 var(--ink); }
.pixel-atmosphere { position: fixed; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 2; opacity: .55; }
.booting .pixel-atmosphere { visibility: hidden; }
.sound-toggle { position: fixed; right: 22px; bottom: max(24px, env(safe-area-inset-bottom)); z-index: 10002; display: flex; gap: 10px; align-items: center; background: #10101de8; color: #f3efe1; border: 1px solid #ffffff50; padding: 12px; font: 10px 'Space Mono', monospace; letter-spacing: 1px; cursor: pointer; text-shadow: none !important; }
.sound-bars { display: flex; align-items: center; gap: 3px; height: 16px; }
.sound-bars i { width: 2px; height: 3px; background: #2fbd8e; }
.sound-on .sound-bars i { animation: equalizer .8s ease-in-out infinite alternate; }
.sound-on .sound-bars i:nth-child(2) { animation-delay: -.5s; }
.sound-on .sound-bars i:nth-child(3) { animation-delay: -.2s; }
@keyframes equalizer { to { height: 16px; } }
.cursor-ring { position: fixed; top: 0; left: 0; width: 32px; height: 32px; border: 1px solid #ffce3d; pointer-events: none; z-index: 10005; opacity: 0; transition: width .2s, height .2s, border-color .2s; mix-blend-mode: difference; }
.cursor-ring.cursor-visible { opacity: 1; }
.cursor-ring.cursor-link { width: 48px; height: 48px; border-color: #2fbd8e; }
@media (pointer: coarse) { .cursor-ring { display: none; } }
@media (max-width: 600px) {
  .sound-toggle { right: 12px; bottom: 18px; padding: 10px 8px; font-size: 8px; }
  .loader-hud { bottom: 24px; left: 18px; width: calc(100vw - 150px); }
  .loader-bottom { font-size: 8px; letter-spacing: .5px; }
  .hero-inner { padding-block: 24px; }
  .hero p.sub { font-size: 14px; }
  .sprite-row { margin-top: 26px; }
  .scroll-cue { margin-top: 24px; }
}

@media (max-width: 860px) {
  .motion-ready .story-pin { top: var(--header-height, 112px); height: calc(100svh - var(--header-height, 112px)); }
  .story-pin { padding: 30px 5vw; }
  .story-line { font-size: clamp(14px, 4.5vw, 38px); }
  .story-label, .story-bottom { font-size: 8px; letter-spacing: 1px; }
  nav.wrap { flex-wrap: wrap; gap: 12px; }
  nav.wrap ul { display: flex; order: 3; width: 100%; overflow-x: auto; white-space: nowrap; gap: 20px; padding-block: 3px; font-size: 11px; }
  .logo { font-size: 12px; }
  .motion-ready .palette { height: 160px; }
  .motion-ready .cart { min-height: 240px; }
  .motion-ready .gallery-pin { top: var(--header-height, 112px); height: calc(100svh - var(--header-height, 112px)); padding-inline: 20px; }
  .motion-ready .gallery-stage .tile { flex-basis: min(74vw, 48svh); width: min(74vw, 48svh); }
  .gallery-caption { font-size: 9px; letter-spacing: 1px; }
  .hero-orbit { inset: 18% 2%; }
  .motion-ready #about, .motion-ready .newsletter { padding-block: 85px; }
  .about-copy .stat-row { gap: 18px; justify-content: space-between; }
  .stat b { font-size: 17px; }
  .stat span { font-size: 10px; }
  .contact-title { font-size: clamp(26px, 7vw, 50px); }
}
/* Pausing motion restores a conventional responsive grid and native scrolling. */
.motion-off *, .motion-off *::before, .motion-off *::after { animation: none !important; transition: none !important; }
html.motion-off { scroll-behavior: auto; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .loader-leaving { animation: none; }
}
@media (pointer: fine) {
  html, body, a, button, input, select, label { cursor: url('https://ayoubazizi-droid.github.io/my-3d-assets-/assets/pixel-cursor.svg') 16 16, crosshair; }
}

/* pix-motion:end */

